global.schema:
type VetraAppState {
  name: String
  slug: String
  owner: EthereumAddress
  status: VetraAppStatus!
  repository: VetraAppRepository
  identity: VetraAppIdentity
  productionEnvironmentId: OID
  previews: VetraAppPreviews
  artifacts: [VetraAppArtifact!]!
}

enum VetraAppStatus {
  PENDING_IDENTITY
  ACTIVE
  DISCONNECTED
  DELETED
}

type VetraAppRepository {
  repositoryId: String
  fullName: String
  productionBranch: String
}

type VetraAppIdentity {
  did: String
  expiresAt: DateTime
}

type VetraAppPreviews {
  enabled: Boolean!
  limit: Int!
  ttlDays: Int!
}

type VetraAppArtifact {
  id: OID!
  kind: VetraAppArtifactKind!
  name: String!
  versions: [VetraAppArtifactVersion!]!
  channels: [VetraAppArtifactChannel!]!
}

enum VetraAppArtifactKind {
  PACKAGE
  FUSION_IMAGE
}

type VetraAppArtifactVersion {
  version: String!
  reference: String!
  commitSha: String
  runId: String
  publishedAt: DateTime!
}

type VetraAppArtifactChannel {
  channel: AutoUpdateChannel!
  version: String!
}

enum AutoUpdateChannel {
  DEV
  STAGING
  LATEST
}

operations.schema:
input SetAppDetailsInput {
  name: String
  slug: String
  owner: EthereumAddress
}

operations.reducer:
if (action.input.name) state.name = action.input.name;
if (action.input.slug) state.slug = action.input.slug;
if (action.input.owner) state.owner = action.input.owner;

operations.schema:
input ConnectRepositoryInput {
  repositoryId: String
  fullName: String
  productionBranch: String
}

operations.reducer:
state.repository = {
  repositoryId: action.input.repositoryId ?? null,
  fullName: action.input.fullName ?? null,
  productionBranch: action.input.productionBranch ?? null,
};

operations.schema:
input SetIdentityInput {
  did: String
  expiresAt: DateTime
}

operations.reducer:
state.identity = {
  did: action.input.did ?? null,
  expiresAt: action.input.expiresAt ?? null,
};

operations.schema:
input SetPreviewsInput {
  enabled: Boolean!
  limit: Int!
  ttlDays: Int!
}

operations.reducer:
state.previews = {
  enabled: action.input.enabled,
  limit: action.input.limit,
  ttlDays: action.input.ttlDays,
};
